  std::string err;
  if (mqtt_ && mqtt_->Publish(topic, json, kQosInstantActions, false, &err)) {
    RCLCPP_INFO(get_logger(), "InstantActions 已下发 MQTT: %s (%zu bytes)", topic.c_str(),
                json.size());

