      if (tracking_mission_id_ == req->mission_id) {
        tracking_mission_id_.clear();
        if (plan_pub_ && plan_pub_->is_activated()) {
          nav_msgs::msg::Path empty;
          empty.header.stamp = now();
          empty.header.frame_id = "map";
          plan_pub_->publish(empty);
