1510:    msg = "navigate_sequence canceled";
1511:  } else if (result.code == rclcpp_action::ResultCode::ABORTED) {
1512:    msg = "navigate_sequence aborted";
1513:  } else {
1514:    msg = "navigate_sequence failed";
1515:  }
1516:  FailMission(mission_id, msg);
