1917:void DispatcherNode::FailMission(const std::string& mission_id, const std::string& reason) {
1918:  std::string order_id;
1919:  amr_dispatcher_core::dispatcher::Mission mission_copy;
1920:  {
1921:    std::lock_guard<std::mutex> lock(active_missions_mutex_);
1922:    auto it = active_missions_.find(mission_id);
1923:    if (it == active_missions_.end()) {
1924:      return;
1925:    }
1926:    order_id = it->second.order_id;
1927:    mission_copy = it->second;
1928:    active_missions_.erase(it);
1929:  }
1930:  // ExecuteMission goal 失败收口（error_code=1）；action 模式取消在途导航 goal
1931:  FinishExecuteGoal(mission_id, ExecuteFinish::kAbort, reason, 1);
1932:  mission_dispatch_time_.erase(mission_id);  // plan 模式无 handle 时的派发时刻遗忘
1933:  ForgetMissionDispatchState(mission_id);    // 路由锁记账/等待记录/派发起点遗忘
1934:  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
1935:    if (nav_client_ && pending_nav_goal_handle_) {
1936:      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1937:    }
1938:    pending_nav_mission_id_.clear();
1939:    pending_nav_goal_handle_.reset();
1940:  }
1941:
1942:  // 失败结果先经 mission_result 行为树分类：资源释放决策 + 失败处理标记
1943:  amr_dispatcher_core::workflow::MissionResultWorkflowInput result_input;
1944:  result_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kFailed;
1945:  result_input.result_success = false;
1946:  result_input.result_message = reason;
1947:  const auto result_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(result_input);
1948:
1949:  if (!result_bt.success || result_bt.decision.release_all_resources) {
1950:    if (reservation_table_) {
1951:      reservation_table_->Release(mission_id);
1952:    }
1953:  }
1954:  if (tracking_mission_id_ == mission_id) {
