1846:void DispatcherNode::CompleteMission(const std::string& mission_id, const std::string& reason) {
1847:  // 单车执行槽位兜底释放：plan 模式由 TrackingErrorCb 先清（幂等）、
1848:  // action 模式由 NavResultCb 收口——此处不清则槽位残留，后续任务永远无法派发（审查 C1）
1849:  if (tracking_mission_id_ == mission_id) {
1850:    tracking_mission_id_.clear();
1851:  }
1852:  std::string order_id;
1853:  {
1854:    std::lock_guard<std::mutex> lock(active_missions_mutex_);
1855:    auto it = active_missions_.find(mission_id);
1856:    if (it == active_missions_.end()) {
1857:      return;
1858:    }
1859:    order_id = it->second.order_id;
1860:    active_missions_.erase(it);
1861:  }
1862:  // ExecuteMission goal 成功收口；action 模式清在途导航 goal（result 到达前的兜底取消）
1863:  FinishExecuteGoal(mission_id, ExecuteFinish::kSucceed, reason, 0);
1864:  mission_dispatch_time_.erase(mission_id);  // plan 模式无 handle 时的派发时刻遗忘
1865:  ForgetMissionDispatchState(mission_id);    // 路由锁记账/等待记录/派发起点遗忘
1866:  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
1867:    if (nav_client_ && pending_nav_goal_handle_) {
1868:      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1869:    }
1870:    pending_nav_mission_id_.clear();
1871:    pending_nav_goal_handle_.reset();
1872:  }
1873:
1874:  // 结果处理走 mission_result 行为树：成功分支给资源释放与失败计数复位决策
1875:  amr_dispatcher_core::workflow::MissionResultWorkflowInput result_input;
1876:  result_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kSucceeded;
1877:  result_input.result_success = true;
1878:  result_input.result_message = reason;
1879:  const auto result_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(result_input);
1880:  RCLCPP_INFO(get_logger(), "Mission %s result via BT: branch=%s state=%s", mission_id.c_str(),
1881:              result_bt.branch.c_str(),
1882:              result_bt.success ? result_bt.decision.state.c_str() : "tree_failed");
1883:
1884:  // 树失败时回退旧行为（无条件释放），防树异常导致资源泄漏
1885:  if (!result_bt.success || result_bt.decision.release_all_resources) {
1886:    if (reservation_table_) {
1887:      reservation_table_->Release(mission_id);
1888:    }
1889:  }
1890:  if (result_bt.success && result_bt.decision.reset_failure_retry_count) {
1891:    mission_attempts_.erase(mission_id);
1892:    mission_last_progress_.erase(mission_id);
1893:  }
1894:  RCLCPP_INFO(get_logger(), "Mission completed: %s (%s)", mission_id.c_str(), reason.c_str());
1895:  if (event_pub_ && event_pub_->is_activated()) {
1896:    amr_dispatcher_interfaces::msg::MissionEvent msg;
1897:    msg.stamp = now();
1898:    msg.mission_id = mission_id;
1899:    msg.order_id = order_id;
1900:    msg.event = "completed";
1901:    msg.from_state = "ACTIVE";
1902:    msg.to_state = "FINISHED";
1903:    msg.reason = reason;
1904:    event_pub_->publish(msg);
1905:  }
1906:  if (event_log_) {
1907:    amr_dispatcher_core::dispatcher::MissionEvent evt;
1908:    evt.stamp = "now";
1909:    evt.mission_id = mission_id;
1910:    evt.event = "completed";
1911:    evt.message = reason;
1912:    event_log_->Append(evt);
1913:  }
1914:  ReArmQueueStartRequest();  // 队列非空时重新武装 runtime 树的启动请求
1915:}
