1293:void DispatcherNode::FinishExecuteGoal(const std::string& mission_id, ExecuteFinish kind,
1294:                                        const std::string& message, std::int32_t error_code) {
1295:  auto it = execute_goal_handles_.find(mission_id);
1296:  if (it == execute_goal_handles_.end()) {
1297:    return;
1298:  }
1299:  auto handle = it->second;
1300:  execute_goal_handles_.erase(it);
1301:
1302:  // total_duration_sec：按派发时刻计时（排队中取消等未派发场景为 0），
1303:  // 计时后即遗忘时间戳，防止 map 长期驻留
1304:  double duration_sec = 0.0;
1305:  auto dispatch_time = mission_dispatch_time_.find(mission_id);
1306:  if (dispatch_time != mission_dispatch_time_.end()) {
1307:    duration_sec = std::chrono::duration<double>(
1308:                       std::chrono::steady_clock::now() - dispatch_time->second)
1309:                       .count();
1310:    mission_dispatch_time_.erase(dispatch_time);
1311:  }
1312:  if (!handle || !handle->is_active()) {
1313:    return;
1314:  }
1315:
1316:  auto result = std::make_shared<ExecuteMission::Result>();
1317:  result->success = (kind == ExecuteFinish::kSucceed);
1318:  result->error_code = error_code;
1319:  result->message = message;
1320:  result->total_duration_sec = duration_sec;
1321:  try {
1322:    if (handle->is_canceling()) {
1323:      // 已受理 action cancel：只能走 canceled()（rclcpp_action 状态机约束）
1324:      handle->canceled(result);
1325:    } else if (handle->is_executing()) {
1326:      if (kind == ExecuteFinish::kSucceed) {
1327:        handle->succeed(result);
1328:      } else {
1329:        // kAbort 与服务侧取消（未进入 CANCELING 无法 canceled()）降级为 abort
1330:        handle->abort(result);
1331:      }
1332:    } else {
1333:      // ACCEPTED 未执行的兜底：先 execute 再 abort，避免 rclcpp_action 状态断言
1334:      handle->execute();
1335:      handle->abort(result);
1336:    }
1337:    RCLCPP_INFO(get_logger(), "ExecuteMission goal finished: %s kind=%d (%s)",
1338:                mission_id.c_str(), static_cast<int>(kind), message.c_str());
1339:  } catch (const std::exception& ex) {
1340:    RCLCPP_ERROR(get_logger(), "FinishExecuteGoal(%s) failed: %s", mission_id.c_str(), ex.what());
1341:  }
1342:}
