2447:void DispatcherNode::Vda5050OnlineCb(const std::string& vehicle_id,
2448:                                     const std_msgs::msg::Bool::SharedPtr msg) {
2449:  auto it = vda5050_links_.find(vehicle_id);
2450:  if (it == vda5050_links_.end()) {
2451:    return;
2452:  }
2453:  if (it->second.online == msg->data) {
2454:    return;  // 状态未变（transient_local 重放/重复报文）：不重复告警
2455:  }
2456:  it->second.online = msg->data;
2457:  if (!msg->data) {
2458:    // Rule 2（Spec §5.2 断链锁定保护）：仅标记离线 + 软看门狗告警，绝不释放任何锁。
2459:    // 锁保留直至该车重连后 state 重核对坐标，或操作员人工强制解除。
2460:    const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
2461:        /*vehicle_online=*/false, /*state_stale=*/false);
2462:    RCLCPP_WARN(get_logger(), "VDA 5050 vehicle %s link broken: %s", vehicle_id.c_str(),
2463:                guard.message.c_str());
2464:    if (event_log_) {
2465:      amr_dispatcher_core::dispatcher::MissionEvent evt;
2466:      evt.stamp = "now";
2467:      evt.mission_id = "-";  // 无任务级事件：链路级看门狗告警
2468:      evt.event = "vehicle_offline";
2469:      evt.message = "vehicle " + vehicle_id + ": retaining all route locks pending "
2470:                    "reconnection and position re-verification (Spec 5.2)";
2471:      event_log_->Append(evt);
2472:    }
2473:  } else {
2474:    RCLCPP_INFO(get_logger(),
2475:                "VDA 5050 vehicle %s back online: locks retained until state re-confirms "
2476:                "lastNodeId against the order (Spec 5.2 position re-verification)",
2477:                vehicle_id.c_str());
2478:  }
2479:}
