2481:bool DispatcherNode::EnforceVda5050LinkGuard() {
2482:  if (vda5050_links_.empty()) {
2483:    return false;  // 未配置受管小车：关闭状态，零开销
2484:  }
2485:  bool blocked = false;
2486:  const auto now = std::chrono::steady_clock::now();
2487:  for (const auto& [vehicle_id, link] : vda5050_links_) {
2488:    if (!link.online) {
2489:      const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
2490:          /*vehicle_online=*/false, /*state_stale=*/false);
2491:      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
2492:                           "Dispatch suspended: %s (vehicle %s). On recovery the vehicle's "
2493:                           "position is re-verified via state before any lock is released.",
2494:                           guard.message.c_str(), vehicle_id.c_str());
2495:      blocked = true;  // 任一受管小车离线即挂起新派发（单车 /plan 执行模型）
2496:      continue;
2497:    }
2498:    if (link.seen_state) {
2499:      const double age_sec =
2500:          std::chrono::duration_cast<std::chrono::milliseconds>(now - link.last_state_time)
2501:              .count() /
2502:          1000.0;
2503:      if (age_sec > vda5050_state_stale_sec_) {
2504:        // 在线但 state 陈旧：仅告警——陈旧不是释放依据，也不阻塞派发（Spec §5.3）
2505:        const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
2506:            /*vehicle_online=*/true, /*state_stale=*/true);
2507:        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000, "VDA 5050 vehicle %s: %s",
2508:                             vehicle_id.c_str(), guard.message.c_str());
2509:      }
2510:    }
2511:  }
2512:  return blocked;
2513:}
