2208:void DispatcherNode::SetupVda5050Links(const std::string& vehicles_param) {
2209:  // 终审 M4：reconfigure 必须先无条件清旧链路态——否则空化 vda5050_vehicle_ids
2210:  // 会残留陈旧 link 继续喂 EnforceVda5050LinkGuard 的挂起守卫（离线车永远
2211:  // 封锁全队派发，且无人工解除途径）。
2212:  vda5050_links_.clear();
2213:  vda5050_vehicle_ids_.clear();
2214:  vda5050_order_pubs_.clear();
2215:  vda5050_next_order_update_id_.clear();
2216:  vda5050_mission_vehicle_.clear();
2217:
2218:  vda5050_state_stale_sec_ = get_parameter("vda5050_state_stale_sec").as_double();
2219:  // 订阅策略：ROS 2 无通配订阅，网关按 MQTT 发现的小车懒建 /fleet/{vid}/* 话题。
2220:  // 采用参数显式清单（逗号分隔 id）——确定性、参数为空时零行为变化，
2221:  // 且订阅先于网关懒建话题也能收到后续消息（ROS 2 订阅者不依赖话题已存在）。
2222:  std::vector<std::string> vehicle_ids;
2223:  std::size_t start = 0;
2224:  while (start <= vehicles_param.size()) {
2225:    const auto end = vehicles_param.find(',', start);
2226:    std::string token = vehicles_param.substr(
2227:        start, end == std::string::npos ? std::string::npos : end - start);
2228:    const auto first = token.find_first_not_of(" \t");
2229:    const auto last = token.find_last_not_of(" \t");
2230:    if (first != std::string::npos) {
2231:      token = token.substr(first, last - first + 1);
2232:      if (std::find(vehicle_ids.begin(), vehicle_ids.end(), token) == vehicle_ids.end()) {
2233:        vehicle_ids.push_back(token);
2234:      }
2235:    }
2236:    if (end == std::string::npos) {
2237:      break;
2238:    }
2239:    start = end + 1;
2240:  }
2241:  if (vehicle_ids.empty()) {
2242:    return;  // 未配置受管小车：逐段解锁/断链守卫整体关闭（现网行为不变）
2243:  }
2244:  for (const auto& vehicle_id : vehicle_ids) {
2245:    auto& link = vda5050_links_[vehicle_id];
2246:    link.state_sub = create_subscription<std_msgs::msg::String>(
2247:        "/fleet/" + vehicle_id + "/state", rclcpp::QoS(10),
2248:        [this, vehicle_id](const std_msgs::msg::String::SharedPtr msg) {
2249:          Vda5050StateCb(vehicle_id, msg);
2250:        });
2251:    // 与网关 online 发布端 QoS 对齐（KeepLast(1) + transient_local），
2252:    // 保证 late-join 的调度端也能收到最近一次链路状态
2253:    link.online_sub = create_subscription<std_msgs::msg::Bool>(
2254:        "/fleet/" + vehicle_id + "/online",
2255:        rclcpp::QoS(rclcpp::KeepLast(1)).transient_local(),
2256:        [this, vehicle_id](const std_msgs::msg::Bool::SharedPtr msg) {
2257:          Vda5050OnlineCb(vehicle_id, msg);
2258:        });
