195:std::vector<std::string> ResourceTable::ReleaseResources(
196:    const std::string& mission_id, const std::vector<std::string>& resource_ids) {
197:  std::vector<std::string> released;
198:  if (mission_id.empty()) {
199:    return released;  // 空 owner 不允许释放任何东西
200:  }
201:  for (const auto& resource_id : resource_ids) {
202:    const auto existing = locks_.find(resource_id);
203:    // 非本任务持有的 id（他人锁/traffic_block/未持有）一律跳过：所有权安全 + 幂等
204:    if (existing == locks_.end() || existing->second != mission_id) {
205:      continue;
206:    }
207:    locks_.erase(existing);
208:    released.push_back(resource_id);
209:  }
210:  return released;
211:}
