230:bool ResourceTable::Unblock(const std::string& resource_id, std::string* message) {
231:  const auto existing = locks_.find(resource_id);
232:  if (existing == locks_.end()) {
233:    if (message != nullptr) {
234:      *message = "resource not locked: " + resource_id;
235:    }
236:    return false;
237:  }
238:  if (!IsTrafficBlockOwner(existing->second)) {
239:    if (message != nullptr) {
240:      *message = "cannot unblock resource held by mission: " + existing->second;
241:    }
242:    return false;
243:  }
244:  locks_.erase(existing);
245:  if (message != nullptr) {
246:    *message = "unblocked " + resource_id;
247:  }
248:  return true;
249:}
