213:bool ResourceTable::Block(const std::string& resource_id, const std::string& reason,
214:                          std::string* message) {
215:  const std::string owner = std::string(kBlockPrefix) + reason;
216:  const auto existing = locks_.find(resource_id);
217:  if (existing != locks_.end()) {
218:    if (message != nullptr) {
219:      *message = "resource already held: " + resource_id + " by " + existing->second;
220:    }
221:    return false;
222:  }
223:  locks_[resource_id] = owner;
224:  if (message != nullptr) {
225:    *message = "blocked " + resource_id;
226:  }
227:  return true;
228:}
