271:std::vector<std::pair<std::string, std::string>> ResourceTable::Snapshot() const {
272:  std::vector<std::pair<std::string, std::string>> out(locks_.begin(), locks_.end());
273:  std::sort(out.begin(), out.end(), [](const auto& lhs, const auto& rhs) {
274:    return lhs.first < rhs.first;
275:  });
276:  return out;
277:}
