572:    return;
573:  }
574:
575:  std::string json;
576:  if (payload.front() == '{') {
577:    json = payload;  // 已是完整 VDA 5050 instantActions JSON，原样透传
578:  } else {
579:    const char* canonical = nullptr;
580:    for (const auto& alias : kInstantActionAliases) {
581:      if (payload == alias.alias) {
582:        canonical = alias.action_type;
583:        break;
584:      }
585:    }
586:    if (canonical == nullptr) {
587:      RCLCPP_WARN(get_logger(),
588:                  "instant_actions 不支持的简单指令 '%s' (vehicle=%s)，"
589:                  "支持: cancelOrder/pause/resume/stopPause，或完整 instantActions JSON",
590:                  payload.c_str(), vehicle_id.c_str());
591:      return;
592:    }
593:    amr_dispatcher_core::fleet::VehicleAction action;
594:    action.action_type = canonical;
595:    action.action_id = "ia_" + std::to_string(g_instant_action_seq.fetch_add(1));
596:    std::vector<amr_dispatcher_core::fleet::VehicleAction> actions{std::move(action)};
597:    json = amr_dispatcher_core::fleet::SerializeVda5050InstantActions(vehicle_id, actions,
598:                                                                     protocol_version_, manufacturer);
599:  }
600:
601:  const std::string topic = MqttTopic(manufacturer, vehicle_id, "instantActions");
602:  std::string err;
603:  if (mqtt_ && mqtt_->Publish(topic, json, kQosInstantActions, false, &err)) {
604:    RCLCPP_INFO(get_logger(), "InstantActions 已下发 MQTT: %s (%zu bytes)", topic.c_str(),
605:                json.size());
606:  } else {
607:    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "InstantActions 下发失败 (topic=%s): %s",
608:                         topic.c_str(),
609:                         (mqtt_ == nullptr) ? "MQTT 子系统未启用" : err.c_str());
610:  }
611:}
