1560:  // 行为树出队派发门控：runtime 树按"空闲 + 启动请求"给派发决策，
1561:  // 未请求启动时即使队列有任务也不出队（启动请求由提单/入队/结果链武装）。
1562:  amr_dispatcher_bt::MissionRuntimeBehaviorTreeInput runtime_input;
1563:  runtime_input.tick.mission_active = !tracking_mission_id_.empty();
1564:  runtime_input.tick.queue_start_requested = queue_start_requested_;
1565:  const auto runtime_result = amr_dispatcher_bt::TickMissionRuntimeBehaviorTree(runtime_input);
1566:  if (!runtime_result.success || !runtime_result.decision.start_queued_mission) {
1567:    return;
1568:  }
1569:  queue_start_requested_ = false;  // 启动请求被本次派发消费
1570:
1571:  // Peek→Reserve→Pop（节点单线程，Peek 与 Pop 之间无竞态）：
1572:  // 先为队首任务规划路由锁并预留，成功才出队继续派发；失败则任务留在队列、
1573:  // 发 reservation_denied 事件、重新武装启动请求后本 tick 返回——既不丢任务也不违反封路。
1574:  const auto* peeked = queue_->Peek();
1575:  if (!peeked) {
1576:    return;  // 队列任务全部暂停：与 PopNext 失败等价，本 tick 结束
1577:  }
1578:  const std::string candidate_id = peeked->id;
1579:  const std::string candidate_order_id = peeked->order_id;
1580:  std::vector<std::string> route_locks;
1581:  if (catalog_reloader_ != nullptr && catalog_reloader_->loaded()) {
1582:    route_locks = amr_dispatcher_core::workflow::PlanMissionRouteLocks(
1583:        catalog_reloader_->catalog(), peeked->pickup_station, peeked->dropoff_station);
1584:  }
1585:  if (!route_locks.empty() && reservation_table_) {
1586:    auto reserve = reservation_table_->Reserve(candidate_id, route_locks);
1587:    if (!reserve.success) {
1588:      pending_wait_[candidate_id] = route_locks;  // WFG：该任务在等这批锁
1589:      RCLCPP_WARN(get_logger(), "Reservation denied for queued mission %s: %s",
1590:                  candidate_id.c_str(), reserve.message.c_str());
1591:      if (event_pub_ && event_pub_->is_activated()) {
1592:        amr_dispatcher_interfaces::msg::MissionEvent msg;
1593:        msg.stamp = now();
1594:        msg.mission_id = candidate_id;
1595:        msg.order_id = candidate_order_id;
1596:        msg.event = "reservation_denied";
1597:        msg.from_state = "PENDING";
1598:        msg.to_state = "PENDING";  // 任务留在队列，状态不变
1599:        msg.reason = reserve.message;
1600:        event_pub_->publish(msg);
1601:      }
1602:      if (event_log_) {
1603:        amr_dispatcher_core::dispatcher::MissionEvent evt;
1604:        evt.stamp = "now";
1605:        evt.mission_id = candidate_id;
1606:        evt.event = "reservation_denied";
1607:        evt.message = reserve.message;
1608:        event_log_->Append(evt);
1609:      }
1610:      ReArmQueueStartRequest();  // 队列非空 -> 稍后锁释放时重试派发
1611:      return;
1612:    }
1613:    mission_reserved_at_[candidate_id] = std::chrono::steady_clock::now();
1614:  }
1615:  pending_wait_.erase(candidate_id);  // 预留通过（或本轮无锁），历史等待记录作废
1616:
1617:  auto pop = queue_->PopNext();
1618:  if (!pop.success || !pop.mission) {
1619:    return;
1620:  }

