1471:    const std::string& mission_id, const GoalHandleNavigate::SharedPtr& /*goal_handle*/,
1472:    const std::shared_ptr<const NavigateSequence::Feedback> feedback) {
1473:  mission_last_progress_[mission_id] = std::chrono::steady_clock::now();  // 喂死锁 idle 启发式
1474:  if (!feedback) {
1475:    return;
1476:  }
1477:  // NavigateSequence feedback -> ExecuteMission feedback 映射
1478:  // （current_index/total -> state_code=2 EXECUTING + percent=index/total*100）
1479:  auto hit = execute_goal_handles_.find(mission_id);
