1488:          ? static_cast<float>(100.0 * static_cast<double>(feedback->current_index) /
1489:                               static_cast<double>(feedback->total_waypoints))
1490:          : 0.0f;
1491:  fb->estimated_remaining_sec = 0.0;
1492:  hit->second->publish_feedback(fb);
