2278:void DispatcherNode::PublishVda5050Order(const std::string& mission_id) {
2279:  if (vda5050_vehicle_ids_.empty()) {
2280:    return;  // 未配置受管 VDA 5050 车辆：无订单发布（现网行为不变）
2281:  }
2282:  if (catalog_reloader_ == nullptr || !catalog_reloader_->loaded()) {
2283:    RCLCPP_WARN(get_logger(),
2284:                "Mission %s: station catalog not loaded, VDA 5050 order NOT published",
2285:                mission_id.c_str());
2286:    return;
2287:  }
2288:  const auto path_it = mission_route_paths_.find(mission_id);
2289:  if (path_it == mission_route_paths_.end() || path_it->second.empty()) {
2290:    RCLCPP_WARN(get_logger(),
2291:                "Mission %s: no archived travel path, VDA 5050 order NOT published",
2292:                mission_id.c_str());
2293:    return;
2294:  }
2295:  if (!reservation_table_) {
2296:    RCLCPP_WARN(get_logger(),
2297:                "Mission %s: reservation table unavailable, VDA 5050 order NOT published",
2298:                mission_id.c_str());
2299:    return;
2300:  }
2301:  // 本单名下实际持有的锁（builder 契约：严禁传全局快照——否则他人锁会被
2302:  // 误判为已放行，向小车下发未获路权的 released=true 边，违反 Spec §5.1）
2303:  std::unordered_set<std::string> held_locks;
2304:  for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
2305:    if (owner == mission_id) {
2306:      held_locks.insert(resource_id);
2307:    }
2308:  }
2309:  // 车辆绑定：保序清单上的 round-robin（简单策略，可换 first-free 而不影响契约；
2310:  // 单车配置下结果恒定）。游标先取后进，跨单轮转。
2311:  const std::size_t idx = vda5050_rr_cursor_ % vda5050_vehicle_ids_.size();
2312:  vda5050_rr_cursor_ = (vda5050_rr_cursor_ + 1) % vda5050_vehicle_ids_.size();
2313:  const std::string vehicle_id = vda5050_vehicle_ids_[idx];
2314:  const std::uint32_t update_id = vda5050_next_order_update_id_[vehicle_id]++;
2315:  const auto& catalog = catalog_reloader_->catalog();
2316:
2317:  const auto order = amr_dispatcher_core::fleet::BuildVda5050OrderFromPath(
2318:      vehicle_id, mission_id, update_id, path_it->second, catalog, held_locks);
2319:  if (!order.has_value()) {
2320:    RCLCPP_WARN(get_logger(),
2321:                "Mission %s -> vehicle %s: BuildVda5050OrderFromPath failed "
2322:                "(path %zu node(s)), VDA 5050 order NOT published",
2323:                mission_id.c_str(), vehicle_id.c_str(), path_it->second.size());
2324:    return;
2325:  }
2326:  const auto pub_it = vda5050_order_pubs_.find(vehicle_id);
2327:  if (pub_it == vda5050_order_pubs_.end() || !pub_it->second ||
2328:      !pub_it->second->is_activated()) {
2329:    RCLCPP_WARN(get_logger(),
2330:                "Mission %s -> vehicle %s: send_order publisher missing/inactive, "
2331:                "VDA 5050 order NOT published",
2332:                mission_id.c_str(), vehicle_id.c_str());
2333:    return;
2334:  }
2335:  std_msgs::msg::String out;
2336:  out.data = amr_dispatcher_core::fleet::SerializeVda5050Order(*order);
2337:  pub_it->second->publish(out);
2338:  // 登记 mission -> 车辆绑定：人工强清离线链路时据此反查"该车名下"的锁归属
2339:  vda5050_mission_vehicle_[mission_id] = vehicle_id;
2340:  RCLCPP_INFO(get_logger(),
2341:              "VDA 5050 order published: mission %s -> /fleet/%s/send_order "
2342:              "(orderId=%s, orderUpdateId=%u, %zu nodes, %zu edges, %zu bytes)",
2343:              mission_id.c_str(), vehicle_id.c_str(), order->order_id.c_str(),
2344:              update_id, order->nodes.size(), order->edges.size(), out.data.size());
2345:}
