1545:  // 直接 return（不消费 queue_start_requested_），哈希恢复一致后派发自动继续。
1546:  map_version_valid_ = true;
1547:  if (!expected_map_hash_.empty() && catalog_reloader_ != nullptr &&
1548:      catalog_reloader_->loaded()) {
1549:    const auto& catalog = catalog_reloader_->catalog();
1550:    if (catalog.map_hash.empty() || catalog.map_hash != expected_map_hash_) {
1551:      map_version_valid_ = false;
1552:      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
1553:                           "Map hash mismatch: expected %s, got %s, dispatching paused",
1554:                           expected_map_hash_.c_str(),
1555:                           catalog.map_hash.empty() ? "<missing>" : catalog.map_hash.c_str());
1556:      return;
1557:    }
1558:  }
